/**
 * Lightweight Self-Contained Markdown Parser with Obsidian Wikilink, Mermaid & Callout Support
 */
(function (global) {
    function escapeHtml(text) {
        return text
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }

    function parseMarkdown(md) {
        if (!md) return "";

        // 1. Normalize line endings
        let src = md.replace(/\r\n/g, "\n").replace(/\r/g, "\n");

        // 2. Extract code blocks (fenced code)
        const codeBlocks = [];
        src = src.replace(/```\s*([a-zA-Z0-9_-]*)[ \t]*\n([\s\S]*?)```/g, function (match, lang, code) {
            const id = "FNCCODEBLOCK" + codeBlocks.length + "TOKENEND";
            const trimmedCode = code.replace(/\n$/, "");
            const cleanLang = (lang || "").trim().toLowerCase();
            if (cleanLang === "mermaid") {
                codeBlocks.push('<div class="mermaid-diagram"><pre class="mermaid">' + escapeHtml(trimmedCode) + '</pre></div>');
            } else {
                const escapedCode = escapeHtml(trimmedCode);
                const langClass = cleanLang ? ' class="language-' + escapeHtml(cleanLang) + '"' : "";
                codeBlocks.push('<pre><code' + langClass + '>' + escapedCode + '</code></pre>');
            }
            return id;
        });

        // 3. Extract inline code
        const inlineCodes = [];
        src = src.replace(/`([^`\n]+)`/g, function (match, code) {
            const id = "INLCODEBLOCK" + inlineCodes.length + "TOKENEND";
            inlineCodes.push('<code>' + escapeHtml(code) + '</code>');
            return id;
        });

        // 4. Obsidian Wikilinks transclusions ![[image.png]]
        src = src.replace(/!\[\[(.*?)\]\]/g, function (match, link) {
            const parts = link.split("|");
            const file = parts[0].trim();
            const alt = (parts.length > 1 ? parts[1].trim() : file);
            return '<img src="' + encodeURI(file) + '" alt="' + escapeHtml(alt) + '" />';
        });

        // 5. Obsidian Wikilinks [[Note Title|Alias]] or [[Note Title]]
        const wikilinks = [];
        src = src.replace(/\[\[(.*?)\]\]/g, function (match, link) {
            const id = "WIKILINKBLOCK" + wikilinks.length + "TOKENEND";
            const parts = link.split("|");
            const target = parts[0].trim();
            const label = parts.length > 1 ? parts[1].trim() : target;
            wikilinks.push('<a href="wikilink:' + encodeURIComponent(target) + '" class="wikilink">' + escapeHtml(label) + '</a>');
            return id;
        });

        // 6. Standard Images ![alt](url)
        src = src.replace(/!\[(.*?)\]\((.*?)\)/g, function (match, alt, url) {
            return '<img src="' + encodeURI(url.trim()) + '" alt="' + escapeHtml(alt) + '" />';
        });

        // 7. Standard Links [text](url)
        const stdlinks = [];
        src = src.replace(/\[(.*?)\]\((.*?)\)/g, function (match, text, url) {
            const id = "STDLINKBLOCK" + stdlinks.length + "TOKENEND";
            stdlinks.push('<a href="' + encodeURI(url.trim()) + '">' + escapeHtml(text) + '</a>');
            return id;
        });

        // 8. Headers (# to ######)
        src = src.replace(/^######\s+(.*?)$/gm, '<h6>$1</h6>');
        src = src.replace(/^#####\s+(.*?)$/gm, '<h5>$1</h5>');
        src = src.replace(/^####\s+(.*?)$/gm, '<h4>$1</h4>');
        src = src.replace(/^###\s+(.*?)$/gm, '<h3>$1</h3>');
        src = src.replace(/^##\s+(.*?)$/gm, '<h2>$1</h2>');
        src = src.replace(/^#\s+(.*?)$/gm, '<h1>$1</h1>');

        // 9. Horizontal Rule (---, ***, ___)
        src = src.replace(/^(?:---|\*\*\*|___)\s*$/gm, '<hr />');

        // 10. Tables
        src = src.replace(/((?:\|[^\n]+\|\r?\n)+)/g, function (tableBlock) {
            const lines = tableBlock.trim().split("\n");
            if (lines.length < 2) return tableBlock;

            // Check delimiter line (e.g. |---|---|)
            if (!/^[\|\s\-:]+$/.test(lines[1])) return tableBlock;

            let html = '<table><thead><tr>';
            const headers = lines[0].split("|").slice(1, -1);
            headers.forEach(function (h) {
                html += '<th>' + h.trim() + '</th>';
            });
            html += '</tr></thead><tbody>';

            for (let i = 2; i < lines.length; i++) {
                if (!lines[i].trim()) continue;
                html += '<tr>';
                const cells = lines[i].split("|").slice(1, -1);
                cells.forEach(function (c) {
                    html += '<td>' + c.trim() + '</td>';
                });
                html += '</tr>';
            }
            html += '</tbody></table>\n';
            return html;
        });

        // 11. Blockquotes & Obsidian Callouts (> [!NOTE])
        src = src.replace(/^>\s*\[!([a-zA-Z0-9_-]+)\]\s*(.*?)$/gm, '<blockquote><strong>[$1]</strong> $2');
        src = src.replace(/^>\s?(.*?)$/gm, '<blockquote>$1</blockquote>');
        // Merge contiguous blockquotes
        src = src.replace(/<\/blockquote>\n<blockquote>/g, '<br/>');

        // 12. Tasklists and Checkboxes
        src = src.replace(/^(\s*)[-\*]\s+\[ \]\s+(.*?)$/gm, '$1<ul><li><input type="checkbox" disabled /> $2</li></ul>');
        src = src.replace(/^(\s*)[-\*]\s+\[[xX]\]\s+(.*?)$/gm, '$1<ul><li><input type="checkbox" checked disabled /> $2</li></ul>');

        // 13. Unordered Lists (- item or * item)
        src = src.replace(/^(\s*)[-\*]\s+(.*?)$/gm, '$1<ul><li>$2</li></ul>');
        // 14. Ordered Lists (1. item)
        src = src.replace(/^(\s*)\d+\.\s+(.*?)$/gm, '$1<ol><li>$2</li></ol>');

        // Merge contiguous lists
        src = src.replace(/<\/ul>\n<ul>/g, '\n');
        src = src.replace(/<\/ol>\n<ol>/g, '\n');

        // 15. Bold, Italic, Strikethrough
        src = src.replace(/\*\*\*(.*?)\*\*\*/g, '<strong><em>$1</em></strong>');
        src = src.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
        src = src.replace(/__(.*?)__/g, '<strong>$1</strong>');
        src = src.replace(/\*(.*?)\*/g, '<em>$1</em>');
        src = src.replace(/_(.*?)_/g, '<em>$1</em>');
        src = src.replace(/~~(.*?)~~/g, '<del>$1</del>');

        // 16. Paragraphs (lines separated by double newlines)
        const paragraphs = src.split(/\n\n+/);
        src = paragraphs.map(function (p) {
            p = p.trim();
            if (!p) return "";
            if (/^<(h[1-6]|ul|ol|table|blockquote|hr|pre|div|p|img)/i.test(p) || /^FNCCODEBLOCK\d+TOKENEND$/.test(p)) {
                return p;
            }
            return '<p>' + p.replace(/\n/g, '<br/>') + '</p>';
        }).join("\n");

        // 17. Restore protected blocks in reverse order
        stdlinks.forEach(function (linkHtml, i) {
            src = src.split("STDLINKBLOCK" + i + "TOKENEND").join(linkHtml);
        });
        wikilinks.forEach(function (linkHtml, i) {
            src = src.split("WIKILINKBLOCK" + i + "TOKENEND").join(linkHtml);
        });
        inlineCodes.forEach(function (code, i) {
            src = src.split("INLCODEBLOCK" + i + "TOKENEND").join(code);
        });
        codeBlocks.forEach(function (code, i) {
            src = src.split("FNCCODEBLOCK" + i + "TOKENEND").join(code);
        });

        return src;
    }

    global.marked = {
        parse: parseMarkdown
    };
})(window);
